import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 9
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    def is_header(record):
        if len(record) != expected_width:
            return False
        labels = [cell.strip().casefold() for cell in record]
        return (
            len(set(labels)) == expected_width
            and all(any(char.isalpha() for char in label) for label in labels)
        )

    first_nonblank = next(
        (i for i, record in enumerate(records)
         if any(cell.strip() for cell in record)),
        None,
    )
    if first_nonblank is None:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i in range(first_nonblank, len(records)) if is_header(records[i])),
        first_nonblank,
    )
    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Preserve overflow fields in additional columns rather than guessing joins.
    used_names = {name.strip().casefold() for name in columns}
    suffix = 1
    while len(columns) < width:
        name = "Extra {}".format(suffix)
        suffix += 1
        if name.casefold() not in used_names:
            columns.append(name)
            used_names.add(name.casefold())

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
